import type { Metadata } from 'next'
import { headers } from 'next/headers'
import { NavigateButton } from '@/components/NavigationButtons'

interface Post {
  id: number
  title: string
  body: string
  userId: number
}

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage() {
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') || ''
  const timestamp = new Date().toISOString()

  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5'
  ).then((res) => res.json())

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <a href={`/blog/${post.id}`}>{post.title}</a>
          </li>
        ))}
      </ul>

      <NavigateButton href="/blog">View All Posts</NavigateButton>
    </div>
  )
}

